-- Pozo modelo (curva de UN pozo individual, Mes 1..N desde su propio
-- arranque) del archivo Pozos_Tipo_ET_PQO_310726.xlsx. Distinto de la curva
-- básica ya cargada (esa es el agregado de campo, usada para el prorrateo de
-- OPEX) -- esta se usa como "curva que activa" en Intervenciones/Campañas
-- para modelar pozos NUEVOS a perforar, uno por uno.
-- días/mes promedio 30.4368 (no hay fecha calendario en el archivo, solo
-- "Mes" 1..N relativo al arranque del pozo).

insert into pozos_tipo (nombre, yacimiento_id, categoria)
select v.nombre, y.id, v.categoria
from (values
  ('GSJ_CH_MODELO', 'El Tordillo', 'basico'),
  ('GSJ_PQO_MODELO', 'LT_PQO', 'basico'),
  ('GSJ_BLG_MODELO', 'Bloque G', 'basico'),
  ('GSJ_WO_MODELO', 'El Tordillo', 'workover')
) as v(nombre, yacimiento, categoria)
join yacimientos y on y.nombre = v.yacimiento
where not exists (select 1 from pozos_tipo pt where pt.nombre = v.nombre);

